CREATE TABLE ship_jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,source_release_id TEXT NOT NULL,version INTEGER NOT NULL,source_digest TEXT NOT NULL,requested_by TEXT NOT NULL REFERENCES users(id),operation TEXT NOT NULL CHECK(operation IN ('deploy','rollback')),rollback_release_id TEXT,status TEXT NOT NULL CHECK(status IN ('queued','building','deploying','checking','succeeded','failed','blocked','timed_out')),reason TEXT,created_at INTEGER NOT NULL,deadline_at INTEGER NOT NULL,finished_at INTEGER,FOREIGN KEY(project_id,source_release_id) REFERENCES source_releases(project_id,id));
CREATE UNIQUE INDEX one_active_ship ON ship_jobs(project_id) WHERE status IN ('queued','building','deploying','checking');
CREATE TABLE ship_events(job_id TEXT NOT NULL REFERENCES ship_jobs(id) ON DELETE CASCADE,seq INTEGER NOT NULL,stage TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(job_id,seq));
CREATE TABLE ship_artifacts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES ship_jobs(id) ON DELETE CASCADE,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,source_digest TEXT NOT NULL,digest TEXT NOT NULL,files_json TEXT NOT NULL,byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 600000),created_at INTEGER NOT NULL);
CREATE TABLE ship_releases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,job_id TEXT NOT NULL UNIQUE REFERENCES ship_jobs(id) ON DELETE CASCADE,artifact_id TEXT NOT NULL REFERENCES ship_artifacts(id) ON DELETE CASCADE,version INTEGER NOT NULL,source_digest TEXT NOT NULL,artifact_digest TEXT NOT NULL,target_id TEXT NOT NULL,url TEXT NOT NULL,health_kind TEXT NOT NULL CHECK(health_kind IN ('local-http','public-http')),checked_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE ship_current(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,release_id TEXT NOT NULL REFERENCES ship_releases(id) ON DELETE CASCADE);
CREATE TRIGGER ship_job_lineage BEFORE UPDATE OF project_id,source_release_id,version,source_digest,requested_by,operation,rollback_release_id,created_at,deadline_at ON ship_jobs BEGIN SELECT RAISE(ABORT,'immutable_deployment_job'); END;
CREATE TRIGGER ship_job_pin BEFORE INSERT ON ship_jobs WHEN NOT EXISTS(SELECT 1 FROM source_releases r WHERE r.project_id=NEW.project_id AND r.id=NEW.source_release_id AND r.version=NEW.version AND r.source_digest=NEW.source_digest) BEGIN SELECT RAISE(ABORT,'deployment_pin_required'); END;
CREATE TRIGGER ship_job_transition BEFORE UPDATE OF status ON ship_jobs WHEN NOT (OLD.status='queued' AND NEW.status IN ('building','blocked','failed','timed_out') OR OLD.status='building' AND NEW.status IN ('deploying','failed','timed_out') OR OLD.status='deploying' AND NEW.status IN ('checking','failed','timed_out') OR OLD.status='checking' AND NEW.status IN ('succeeded','failed','timed_out')) BEGIN SELECT RAISE(ABORT,'deployment_transition_denied'); END;
CREATE TRIGGER ship_artifact_immutable BEFORE UPDATE ON ship_artifacts BEGIN SELECT RAISE(ABORT,'immutable_ship_artifact'); END;
CREATE TRIGGER ship_artifact_pin BEFORE INSERT ON ship_artifacts WHEN NOT EXISTS(SELECT 1 FROM ship_jobs j WHERE j.id=NEW.job_id AND j.project_id=NEW.project_id AND j.source_digest=NEW.source_digest AND j.status='building') BEGIN SELECT RAISE(ABORT,'artifact_job_required'); END;
CREATE TRIGGER ship_release_immutable BEFORE UPDATE ON ship_releases BEGIN SELECT RAISE(ABORT,'immutable_ship_release'); END;
CREATE TRIGGER ship_event_immutable BEFORE UPDATE ON ship_events BEGIN SELECT RAISE(ABORT,'immutable_ship_event'); END;
CREATE TRIGGER ship_release_health BEFORE INSERT ON ship_releases WHEN NOT EXISTS(SELECT 1 FROM ship_jobs j JOIN ship_artifacts a ON a.job_id=j.id WHERE j.id=NEW.job_id AND j.project_id=NEW.project_id AND j.status='checking' AND j.version=NEW.version AND j.source_digest=NEW.source_digest AND a.id=NEW.artifact_id AND a.digest=NEW.artifact_digest AND NEW.checked_at>=j.created_at) BEGIN SELECT RAISE(ABORT,'verified_release_required'); END;
CREATE TRIGGER ship_current_project BEFORE INSERT ON ship_current WHEN NOT EXISTS(SELECT 1 FROM ship_releases r WHERE r.id=NEW.release_id AND r.project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'current_release_project'); END;
CREATE TRIGGER ship_current_update BEFORE UPDATE ON ship_current WHEN NOT EXISTS(SELECT 1 FROM ship_releases r WHERE r.id=NEW.release_id AND r.project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'current_release_project'); END;
CREATE TRIGGER ship_rollback_pin BEFORE INSERT ON ship_jobs WHEN NEW.operation='rollback' AND NOT EXISTS(SELECT 1 FROM ship_releases r WHERE r.id=NEW.rollback_release_id AND r.project_id=NEW.project_id AND r.version=NEW.version AND r.source_digest=NEW.source_digest) BEGIN SELECT RAISE(ABORT,'known_good_rollback_required'); END;
CREATE TRIGGER ship_release_owner BEFORE INSERT ON ship_releases WHEN NOT EXISTS(SELECT 1 FROM ship_jobs j JOIN projects p ON p.id=j.project_id JOIN memberships m ON m.workspace_id=p.workspace_id AND m.user_id=j.requested_by WHERE j.id=NEW.job_id AND m.role='owner') BEGIN SELECT RAISE(ABORT,'deployment_owner_changed'); END;
